insert into public.agent_findings (id, agent_id, type, title, summary, confidence, created_at, evidence, source_ids, requires_human_review, status, data_origin, author_id, updated_at) values ('10000000-0000-4000-8000-000000000040', '10000000-0000-4000-8000-000000000031', 'audience', 'Devotion is getting their attention.', 'Protective and devoted love-interest language appears more often in the synthetic sample. Test the positioning only after you confirm audience fit and book relevance.', 0.82, '2026-09-17T12:00:00.000Z', '[{"id":"10000000-0000-4000-8000-000000000020","source_id":"10000000-0000-4000-8000-000000000010","source":"Synthetic reader-language sample","source_type":"synthetic","retrieved_at":"2026-09-17T12:00:00.000Z","excerpt_or_metric":"In 40 invented reader comments, 18 mention protective or devoted love interests. In an earlier invented sample of 40, 9 do. These are fabricated examples, not collected reader comments.","metadata":{"sample_size":40,"mentions":18,"previous_mentions":9,"no_catalog_trope_claim":true},"data_origin":"demo"}]'::jsonb, ARRAY['10000000-0000-4000-8000-000000000010']::uuid[], true, 'new', 'demo', '10000000-0000-4000-8000-000000000001', '2026-09-17T12:00:00.000Z') on conflict do nothing;
insert into public.agent_findings (id, agent_id, type, title, summary, confidence, created_at, evidence, source_ids, requires_human_review, status, data_origin, author_id, updated_at) values ('10000000-0000-4000-8000-000000000041', '10000000-0000-4000-8000-000000000033', 'catalog', 'Give every title a source of truth.', 'Review the My Alpha Team catalog records and verify metadata before any marketing claims are generated.', 0.94, '2026-09-17T12:00:00.000Z', '[{"id":"10000000-0000-4000-8000-000000000021","source_id":"10000000-0000-4000-8000-000000000012","source":"Kira Stanley · My Alpha Team","source_type":"website","retrieved_at":"2026-09-17T12:00:00.000Z","excerpt_or_metric":"The official collection lists Crazy People (#1), Agent People (#2), and Us People (#3). Only titles and ordering have been recorded; tropes remain unverified.","metadata":{"url":"https://www.kirastanleyauthor.com/myalphateam"},"data_origin":"public_verified"}]'::jsonb, ARRAY['10000000-0000-4000-8000-000000000012']::uuid[], true, 'new', 'demo', '10000000-0000-4000-8000-000000000001', '2026-09-17T12:00:00.000Z') on conflict do nothing;
